'use strict';
(function(){
const G=MaisonGoals;let soundContext=null,shown=null,renderKey=null;
function unlock(){if(!soundContext){const Audio=window.AudioContext||window.webkitAudioContext;if(Audio)soundContext=new Audio();}if(soundContext?.state==='suspended')soundContext.resume().catch(()=>{});}
document.addEventListener('pointerdown',unlock,{once:true});document.addEventListener('keydown',unlock,{once:true});
function chime(){if(!window.MaisonStartUI?.settings.sound||!soundContext||soundContext.state!=='running')return;[523.25,659.25,783.99].forEach((frequency,i)=>{const o=soundContext.createOscillator(),g=soundContext.createGain(),t=soundContext.currentTime+i*.09;o.frequency.value=frequency;o.type='sine';g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.08,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.25);o.connect(g);g.connect(soundContext.destination);o.start(t);o.stop(t+.26);});}
function renderGoals(){const el=$('#guidance');if(window.homeOpen||!saved){el.hidden=true;return;}el.hidden=false;const g=G.update(state);if(g.notifications.length){shown=g.notifications.splice(0).at(-1);g.open=true;chime();save();}const current=G.current(state),completed=G.tasks.find(x=>x.id===shown);const key=JSON.stringify([g.open,g.done,g.needsRework,g.onTime,shown,W.week(state)>=g.deadlineWeek]);if(key===renderKey)return;renderKey=key;el.classList.toggle('collapsed',!g.open);el.innerHTML=`<button class="guidance-toggle" aria-expanded="${g.open}" title="Ouvrir ou fermer les objectifs"><span>✦ ${g.open?'Tes premiers accords':'Objectifs'}</span><b>${g.open?'−':'＋'}</b></button>${g.open?`<div class="guidance-content" aria-live="polite"><span class="eyebrow">${g.done.length} ÉTAPE${g.done.length>1?'S':''} ACCOMPLIE${g.done.length>1?'S':''}</span>${completed?`<div class="goal-done"><span>✓</span><s>${completed.title}</s></div>`:''}${current?`<h3>${current.title}</h3><p>${I.esc(current.id==='ready'&&W.week(state)>=g.deadlineWeek?'Prépare une chanson pour la scène. Le premier rendez-vous est arrivé : la progression continue à ton rythme.':current.text)}</p><button id="goalAction" class="quiet">${current.id==='write'?'Voir les compositions':'Ouvrir le répertoire'} ↗</button>`:`<h3>La maison a trouvé son rythme !</h3><p>${g.onTime===false?'La préparation est acquise. Continue à enrichir le répertoire pour les prochains shows.':'Tes premières chansons sont prêtes. À toi de faire grandir le collectif.'}</p>`}${!g.needsRework&&g.done.includes('propose')?'<small>La seconde chance apparaîtra si une chanson est refusée.</small>':''}</div>`:''}`;el.querySelector('.guidance-toggle').onclick=()=>{g.open=!g.open;save();renderGoals();};if($('#goalAction'))$('#goalAction').onclick=()=>{document.querySelector('[data-rail-tab="repertoire"]')?.click();$('#songbook').scrollIntoView({behavior:window.MaisonStartUI?.settings.reducedMotion?'auto':'smooth',block:'nearest'});};}
window.MaisonGuidanceUI={render:renderGoals,reset:()=>{shown=null;renderKey=null;}};
})();
